521	TfLiteStatus Subgraph::ReplaceNodeSubsetsWithDelegateKernels(
522	    TfLiteRegistration registration, const TfLiteIntArray* nodes_to_replace,
523	    TfLiteDelegate* delegate) {
524	  // Annotate the registration as DELEGATE op.
525	  registration.builtin_code = BuiltinOperator_DELEGATE;
526	  if (registration.registration_external) {
527	    registration.registration_external->builtin_code = BuiltinOperator_DELEGATE;
528	  }
529	
530	  // The subgraph is taking ownership of the external registration, in case the
531	  // user has supplied an opaque delegate.
532	  if (TfLiteDelegateIsOpaque(delegate)) {
533	    // If the user has supplied an opaque delegate, then they _must_ also use
534	    // TfLiteOperator.
535	    if (!registration.registration_external) {
536	      TFLITE_LOG(
537	          tflite::TFLITE_LOG_WARNING,
538	          "For a delegate with the 'opaque_delegate_builder' field set, the "
539	          "delegate kernel's TfLiteRegistration object must have the "
540	          "'registration_external' field set.");
541	      return kTfLiteDelegateError;
542	    }
543	
544	    // In this case, the subgraph takes ownership of the external registration.
545	    OpResolver::OpId op_id{registration.registration_external->builtin_code,
546	                           registration.registration_external->custom_name,
547	                           registration.registration_external->version};
548	    auto [it, inserted] = registration_externals_->emplace(
549	        op_id,
550	        std::unique_ptr<TfLiteOperator>(registration.registration_external));
551	    // If there was already an entry for this op_id in the
552	    // registration_externals_ cache, the statement above will have
553	    // no effect on the registration_externals_ cache,
554	    // but will deallocate registration.registration_externals.
555	    // To ensure that registration remains valid, we need to use the
556	    // registration_externals value that was previously in the cache.
557	    if (!inserted) {
558	      auto registration_external_from_cache = it->second.get();
559	      registration.registration_external = registration_external_from_cache;
560	    }
561	  }
562	
563	  // Ignore empty node replacement sets.
564	  if (!nodes_to_replace->size) {
565	    return kTfLiteOk;
566	  }
567	
568	  // Analyze the graph to find all independent node_subsets that are either
569	  // fully not-this-delegate or this-delegate computation.
570	  std::vector<NodeSubset> node_subsets;
571	  if (PartitionGraph(nodes_to_replace, &node_subsets) == kTfLiteError) {
572	    return kTfLiteError;
573	  }
574	
575	  // On Android the log message below is used for diagnosing delegation success
576	  // also in production builds. Use VERBOSE here so that the logging is turned
577	  // off in production builds on other platforms.
578	  TFLITE_LOG_PROD(tflite::TFLITE_LOG_VERBOSE,
579	                  "Replacing %d out of %d node(s) with delegate (%s) node, "
580	                  "yielding %zu partitions "
581	                  "for subgraph %d (%s).",
582	                  nodes_to_replace->size, execution_plan_.size(),
583	                  GetDelegateKernalName(registration), node_subsets.size(),
584	                  subgraph_index_, name_.c_str());
585	
586	  execution_plan_.clear();
587	
588	  for (auto& node_subset : node_subsets) {
589	    // Subsets claimed by the delegate should have a "macro" op created, the
590	    // other node_subsets (kTfNonPartition) just have their nodes added back to
591	    // the execution plan.
592	    switch (node_subset.type) {
593	      case NodeSubset::kTfNonPartition:
594	        for (auto it = node_subset.nodes.begin(); it != node_subset.nodes.end();
595	             ++it) {
596	          execution_plan_.push_back(*it);
597	        }
598	        break;
599	      case NodeSubset::kTfPartition: {
600	        int node_index;
601	
602	        void* delegate_params = nullptr;
603	        if (TfLiteDelegateIsOpaque(delegate)) {
604	          TfLiteOpaqueDelegateParams* opaque_params =
605	              CreateOpaqueDelegateParams(delegate, node_subset);
606	          delegate_params = opaque_params;
607	        } else {
608	          TfLiteDelegateParams* params =
609	              CreateDelegateParams(delegate, node_subset);
610	          delegate_params = params;
611	        }
612	        TF_LITE_ENSURE_STATUS(AddNodeWithParameters(
613	            node_subset.input_tensors, node_subset.output_tensors, {}, nullptr,
614	            0, delegate_params, &registration, &node_index));
615	
616	        // Initialize the output tensors's delegate-related fields.
617	        for (int tensor_index : node_subset.output_tensors) {
618	          TfLiteTensor* tensor = &tensors_[tensor_index];
619	          TF_LITE_ENSURE(&context_, tensor->delegate == nullptr ||
620	                                        tensor->delegate == delegate);
621	          tensor->delegate = delegate;
622	        }
623	
624	        // Associate the node with the delegate.
625	        TfLiteNode* node = &nodes_and_registration_[node_index].first;
626	        node->delegate = delegate;
627	      } break;
628	      case NodeSubset::kTfUnexplored:
629	        return kTfLiteError;
630	        break;
631	    }
632	  }
633	  return kTfLiteOk;
634	}
